import os,re,subprocess,sys
cn=os.environ.get('COMPUTERNAME',''); un=os.environ.get('USERNAME','')
ps={p.lower() for n in (un, cn) for p in re.findall(r'[A-Z][a-z]+|[a-z]+|[A-Z0-9]+(?![a-z])', n) + [n] if len(p) >= 5}
if '-' in cn:
    a, b = cn.split('-', 1); ps.add((a + '-' + b[:2]).lower())
ps -= {'users', 'admin', 'public', 'windows'}
fs=[f for f in subprocess.run(['git','ls-files','-z'],capture_output=True,text=True,encoding='utf-8').stdout.split(chr(0)) if f]
hit=[f for f in fs if ps and any(p in open(f,encoding='utf-8',errors='ignore').read().lower() for p in ps)]
print(hit); sys.exit(1 if hit else 0)

